import json, hashlib, statistics, itertools, copy, math
from importlib.metadata import version
from pathlib import Path

r=Path('.agent-runs/performance-v2')
rows=[]
raw_hashes={}
environments=[]
for seed in range(2501,2505):
    for label,model,regime in itertools.product(['before','after'],['rf','et'],['fixed','timer'] if seed!=2504 else ['balanced','wide']):
        p=r/f'fast-forest-{label}-{model}-{regime}-{seed}.json'
        raw_hashes[p.name]=hashlib.sha256(p.read_bytes()).hexdigest()
        data=json.loads(p.read_text(encoding='utf-8'))
        environment={k:data['settings'][k] for k in ['python','sklearn','numpy']}
        if environment not in environments:environments.append(environment)
        assert data['settings']['cpu']==1 and data['settings']['folds']==3
        assert len(data['results'])==(1 if seed==2504 else 4)
        for row in data['results']:
            assert (row['label'],row['model'],row['regime'],row['seed'])==(label,model,regime,seed)
            assert not set(row['train_indices']).intersection(row['test_indices'])
            expected_size={'control':80,'diabetes':442,'friedman800':800,'friedman2400':2400,'outliers':800}[row['dataset']]
            assert sorted(row['train_indices']+row['test_indices'])==list(range(expected_size))
            validation=[]
            for fold in row['folds']:
                assert not set(fold['train']).intersection(fold['validation'])
                assert sorted(fold['train']+fold['validation'])==list(range(len(row['train_indices'])))
                validation.extend(fold['validation'])
            assert sorted(validation)==list(range(len(row['train_indices'])))
            criteria={params['criterion'] for params in row['candidates']['params']}
            assert criteria<=({'squared_error'} if label=='after' and seed!=2504 else {'squared_error','absolute_error'})
            assert len(row['candidates']['params'])==len(row['candidates']['scores'])>0
            assert all(math.isfinite(value) for value in row['candidates']['scores'])
            assert row['cv_score']==max(row['candidates']['scores'])
            assert any(params==row['params'] and score==row['cv_score'] for params,score in zip(row['candidates']['params'],row['candidates']['scores']))
        rows.extend(data['results'])
assert len(rows)==104
assert len(environments)==1
paired={}
for row in rows:
    key=(row['model'],row['regime'],row['dataset'],row['seed'])
    assert row['label'] not in paired.setdefault(key,{})
    paired[key][row['label']]=row
for key,pair in paired.items():
    assert set(pair)=={'before','after'}
    before,after=pair['before'],pair['after']
    for field in ['data_sha256','train_indices','test_indices','folds','scoring']:
        assert before[field]==after[field],(key,field)
    if key[1] in ['balanced','wide']:
        for field in ['candidate_scores_sha256','prediction_sha256','params','cv_score','mse','mae','fit_stats']:
            assert before[field]==after[field],(key,field)
groups=[]
for model,regime,dataset in itertools.product(['rf','et'],['fixed','timer'],['diabetes','friedman800','friedman2400','outliers']):
    entry=dict(model=model,regime=regime,dataset=dataset)
    for label in ['before','after']:
        selected=[row for row in rows if (row['model'],row['regime'],row['dataset'],row['label'])==(model,regime,dataset,label)]
        assert len(selected)==3
        stats={metric:dict(mean=statistics.mean(row[metric] for row in selected),std=statistics.stdev(row[metric] for row in selected)) for metric in ['seconds','mse','mae','cv_score']}
        stats['mean_cv_calls']=statistics.mean(row['fit_stats']['cross_validate_calls'] for row in selected)
        entry[label]=stats
    metric='mae' if dataset=='outliers' else 'mse'
    entry['speedup']=entry['before']['seconds']['mean']/entry['after']['seconds']['mean']
    entry['heldout_error_change_percent']=100*(entry['after'][metric]['mean']/entry['before'][metric]['mean']-1)
    groups.append(entry)
